-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_constructorResults AS SELECT constructorResults.constructorResultsId AS constructorResultsId, constructorResults.points AS points, constructorResults.status AS status, races.year AS year, races.round AS round, races.circuitId AS circuitId, races.name AS name, races.date AS date, races.time AS time, races.url AS url, constructors.constructorRef AS constructorRef, constructors.name AS constructor_name, constructors.nationality AS nationality, constructors.url AS constructor_url FROM constructorResults LEFT JOIN races ON constructorResults.raceId = races.raceId LEFT JOIN constructors ON constructorResults.constructorId = constructors.constructorId;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_constructorStandings AS SELECT constructorStandings.constructorStandingsId AS constructorStandingsId, constructorStandings.raceId AS raceId, constructorStandings.points AS points, constructorStandings.position AS position, constructorStandings.positionText AS positionText, constructorStandings.wins AS wins, constructors.constructorRef AS constructorRef, constructors.name AS name, constructors.nationality AS nationality, constructors.url AS url FROM constructorStandings LEFT JOIN constructors ON constructorStandings.constructorId = constructors.constructorId;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_driverStandings AS SELECT driverStandings.driverStandingsId AS driverStandingsId, driverStandings.points AS points, driverStandings.position AS position, driverStandings.positionText AS positionText, driverStandings.wins AS wins, races.year AS year, races.round AS round, races.circuitId AS circuitId, races.name AS name, races.date AS date, races.time AS time, races.url AS url, drivers.driverRef AS driverRef, drivers.number AS number, drivers.code AS code, drivers.forename AS forename, drivers.surname AS surname, drivers.dob AS dob, drivers.nationality AS nationality, drivers.url AS driver_url FROM driverStandings LEFT JOIN races ON driverStandings.raceId = races.raceId LEFT JOIN drivers ON driverStandings.driverId = drivers.driverId;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_lapTimes AS SELECT lapTimes.raceId AS raceId, lapTimes.driverId AS driverId, lapTimes.lap AS lap, lapTimes.position AS position, lapTimes.time AS time, lapTimes.milliseconds AS milliseconds, races.year AS year, races.round AS round, races.circuitId AS circuitId, races.name AS name, races.date AS date, races.time AS race_time, races.url AS url, drivers.driverRef AS driverRef, drivers.number AS number, drivers.code AS code, drivers.forename AS forename, drivers.surname AS surname, drivers.dob AS dob, drivers.nationality AS nationality, drivers.url AS driver_url FROM lapTimes LEFT JOIN races ON lapTimes.raceId = races.raceId LEFT JOIN drivers ON lapTimes.driverId = drivers.driverId;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_pitStops AS SELECT pitStops.raceId AS raceId, pitStops.driverId AS driverId, pitStops.stop AS stop, pitStops.lap AS lap, pitStops.time AS time, pitStops.duration AS duration, pitStops.milliseconds AS milliseconds, drivers.driverRef AS driverRef, drivers.number AS number, drivers.code AS code, drivers.forename AS forename, drivers.surname AS surname, drivers.dob AS dob, drivers.nationality AS nationality, drivers.url AS url FROM pitStops LEFT JOIN drivers ON pitStops.driverId = drivers.driverId;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_qualifying AS SELECT qualifying.qualifyId AS qualifyId, qualifying.constructorId AS constructorId, qualifying.number AS number, qualifying.position AS position, qualifying.q1 AS q1, qualifying.q2 AS q2, qualifying.q3 AS q3, races.year AS year, races.round AS round, races.name AS name, races.date AS date, races.time AS time, races.url AS url, drivers.driverRef AS driverRef, drivers.number AS driver_number, drivers.code AS code, drivers.forename AS forename, drivers.surname AS surname, drivers.dob AS dob, drivers.nationality AS nationality, drivers.url AS driver_url, circuits.circuitRef AS circuitRef, circuits.name AS circuit_name, circuits.location AS location, circuits.country AS country, circuits.lat AS lat, circuits.lng AS lng, circuits.alt AS alt, circuits.url AS circuit_url FROM qualifying LEFT JOIN races ON qualifying.raceId = races.raceId LEFT JOIN drivers ON qualifying.driverId = drivers.driverId LEFT JOIN circuits ON races.circuitId = circuits.circuitId;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_races AS SELECT races.raceId AS raceId, races.round AS round, races.name AS name, races.date AS date, races.time AS time, races.url AS url, seasons.url AS seasons, circuits.circuitRef AS circuitRef, circuits.name AS circuit_name, circuits.location AS location, circuits.country AS country, circuits.lat AS lat, circuits.lng AS lng, circuits.alt AS alt, circuits.url AS circuit_url FROM races LEFT JOIN seasons ON races.year = seasons.year LEFT JOIN circuits ON races.circuitId = circuits.circuitId;

-- origin=oracle row_preserving=True check=rows_equal
CREATE VIEW v_results AS SELECT results.resultId AS resultId, results.number AS number, results.grid AS grid, results.position AS position, results.positionText AS positionText, results.positionOrder AS positionOrder, results.points AS points, results.laps AS laps, results.time AS time, results.milliseconds AS milliseconds, results.fastestLap AS fastestLap, results.rank AS rank, results.fastestLapTime AS fastestLapTime, results.fastestLapSpeed AS fastestLapSpeed, races.year AS year, races.round AS round, races.name AS name, races.date AS date, races.time AS race_time, races.url AS url, drivers.driverRef AS driverRef, drivers.number AS driver_number, drivers.code AS code, drivers.forename AS forename, drivers.surname AS surname, drivers.dob AS dob, drivers.nationality AS nationality, drivers.url AS driver_url, constructors.constructorRef AS constructorRef, constructors.name AS constructor_name, constructors.nationality AS constructor_nationality, constructors.url AS constructor_url, status.status AS status, circuits.circuitRef AS circuitRef, circuits.name AS circuit_name, circuits.location AS location, circuits.country AS country, circuits.lat AS lat, circuits.lng AS lng, circuits.alt AS alt, circuits.url AS circuit_url FROM results LEFT JOIN races ON results.raceId = races.raceId LEFT JOIN drivers ON results.driverId = drivers.driverId LEFT JOIN constructors ON results.constructorId = constructors.constructorId LEFT JOIN status ON results.statusId = status.statusId LEFT JOIN circuits ON races.circuitId = circuits.circuitId;
